messages.content:
 1	method CopyMatrix(src: array2, dst: array2)
 2	    requires src.Length0 == dst.Length0 && src.Length1 == dst.Length1
 3	    modifies dst
 4	    ensures forall i, j :: 0 <= i < src.Length0 && 0 <= j < src.Length1 ==> dst[i,j] == old(src[i,j]) 
 5	{
 6	    var m := 0;
 7	    while m != src.Length0
 8	        invariant 0 <= m <= src.Length0
 9	        invariant forall i, j :: 0 <= i < m && 0 <= j < src.Length1 ==> dst[i,j] == old(src[i,j]) 
10	        invariant forall i, j :: 0 <= i < src.Length0 && 0 <= j < src.Length1 ==> src[i,j] == old(src[i,j])
11	    {
12	        var n := 0;
13	        while n != src.Length1
14	            invariant 0 <= n <= src.Length1 
15	            invariant forall i, j :: 0 <= i < src.Length0 && 0 <= j < src.Length1 ==> src[i,j] == old(src[i,j])
16	            invariant forall j :: 0 <= j < n ==> dst[m,j] == old(src[m,j])
17	        {
18	            dst[m,n] := src[m,n]; n := n + 1;
19	        }
20	        m := m + 1; 
21	    }
22	}

